#ifndef ZEPHIR_RELEASE
static PHP_MSHUTDOWN_FUNCTION(qt)
{
	
	zephir_deinitialize_memory();
	UNREGISTER_INI_ENTRIES();
	return SUCCESS;
}
#endif

/**
 * Initialize globals on each request or each thread started
 */
static void php_zephir_init_globals(zend_qt_globals *qt_globals)
{
	qt_globals->initialized = 0;

	/* Cache Enabled */
	qt_globals->cache_enabled = 1;

	/* Recursive Lock */
	qt_globals->recursive_lock = 0;

	/* Static cache */
	memset(qt_globals->scache, '\0', sizeof(zephir_fcall_cache_entry*) * ZEPHIR_MAX_CACHE_SLOTS);

	
	
}

/**
 * Initialize globals only on each thread started
 */
static void php_zephir_init_module_globals(zend_qt_globals *qt_globals)
{
	
}

static PHP_RINIT_FUNCTION(qt)
{
	zend_qt_globals *qt_globals_ptr;
	qt_globals_ptr = ZEPHIR_VGLOBAL;

	php_zephir_init_globals(qt_globals_ptr);
	zephir_initialize_memory(qt_globals_ptr);

	
	return SUCCESS;
}

static PHP_RSHUTDOWN_FUNCTION(qt)
{
	
	zephir_deinitialize_memory();
	return SUCCESS;
}



static PHP_MINFO_FUNCTION(qt)
{
	php_info_print_box_start(0);
	php_printf("%s", PHP_QT_DESCRIPTION);
	php_info_print_box_end();

	php_info_print_table_start();
	php_info_print_table_header(2, PHP_QT_NAME, "enabled");
	php_info_print_table_row(2, "Author", PHP_QT_AUTHOR);
	php_info_print_table_row(2, "Version", PHP_QT_VERSION);
	php_info_print_table_row(2, "Build Date", __DATE__ " " __TIME__ );
	php_info_print_table_row(2, "Powered by Zephir", "Version " PHP_QT_ZEPVERSION);
	php_info_print_table_end();
	
	DISPLAY_INI_ENTRIES();
}

static PHP_GINIT_FUNCTION(qt)
{
#if defined(COMPILE_DL_QT) && defined(ZTS)
	ZEND_TSRMLS_CACHE_UPDATE();
#endif

	php_zephir_init_globals(qt_globals);
	php_zephir_init_module_globals(qt_globals);
}

static PHP_GSHUTDOWN_FUNCTION(qt)
{
	
}


